additionalExercises.referenceSolution:
#include <iostream>
#include <print>
#include <string>

int depth = 0;

class Indent {
public:
    Indent() : saved_(depth) {
        ++depth;
    }
    ~Indent() {
        depth = saved_;
    }
    Indent(const Indent &) = delete;
    Indent &operator=(const Indent &) = delete;

private:
    int saved_;
};

void print_line(const std::string &text) {
    std::println("{}{}", std::string(depth * 2, ' '), text);
}

void process(std::istream &in, bool nested);

void section(std::istream &in) {
    const Indent indent;
    process(in, true);
}

void process(std::istream &in, bool nested) {
    std::string command;
    while (in >> command) {
        if (command == "end" && nested) {
            return;
        }
        std::string text;
        in >> text;
        if (command == "begin") {
            print_line(text + ":");
            section(in);
        } else {
            print_line(text);
        }
    }
}

int main() {
    process(std::cin, false);
    return 0;
}

