additionalExercises.referenceSolution:
#include <iostream>
#include <print>
#include <stdexcept>
#include <string>

struct State {
    std::string color = "чёрный";
    int width = 1;
};

State current;

class StateSaver {
public:
    StateSaver() : saved_(current) {}
    ~StateSaver() {
        current = saved_;
    }
    StateSaver(const StateSaver &) = delete;
    StateSaver &operator=(const StateSaver &) = delete;

private:
    State saved_;
};

void execute(const std::string &command, std::istream &in);

void block(std::istream &in) {
    const StateSaver saver;
    std::string command;
    while (in >> command) {
        if (command == "restore") {
            return;
        }
        execute(command, in);
    }
}

void execute(const std::string &command, std::istream &in) {
    if (command == "color") {
        in >> current.color;
    } else if (command == "width") {
        in >> current.width;
    } else if (command == "draw") {
        std::string name;
        in >> name;
        std::println("{}: цвет {}, толщина {}", name, current.color, current.width);
    } else if (command == "save") {
        block(in);
    } else if (command == "error") {
        throw std::runtime_error("ошибка рисования");
    }
}

int main() {
    std::string command;
    while (std::cin >> command) {
        try {
            execute(command, std::cin);
        } catch (const std::exception &e) {
            std::println("{}", e.what());
        }
    }
    return 0;
}

